277	interface FormatterOptions {
278	  includeRawJson?: boolean; // Include raw JSON at the end
279	  compact?: boolean; // More compact formatting
280	}
281	
282	/**
283	 * Format any tool result as markdown
284	 */
285	export function formatToolResult(
286	  toolName: string,
287	  result: any,
288	  options: FormatterOptions = {}
289	): string {
290	  const formatters: Record<string, (result: any, options: FormatterOptions) => string> = {
291	    search_memory: formatSearchResult,
292	    get_behavior: formatGetBehaviorResult,
293	    read_knowledge: formatGetContentResult,
294	    manage_behaviors: formatManageBehaviorsResult,
295	    query_sql: formatQuerySqlResult,
296	    render_lobu_view: formatLobuViewResult,
297	  };
298	
299	  const formatter = formatters[toolName];
300	  if (formatter) {
301	    const markdown = formatter(result, options);
302	
303	    // Optionally append raw JSON
304	    if (options.includeRawJson) {
305	      return `${markdown}\n\n---\n\n<details>\n<summary>Raw JSON</summary>\n\n\`\`\`json\n${JSON.stringify(result, null, 2)}\n\`\`\`\n\n</details>`;
306	    }
307	
308	    return markdown;
309	  }
310	
311	  // Fallback: pretty-print JSON
312	  return `\`\`\`json\n${JSON.stringify(result, null, 2)}\n\`\`\``;
313	}
