315	function escapeLobuViewMarkdown(value: unknown, singleLine = false): string {
316	  const text = String(value ?? '');
317	  const normalized = singleLine ? text.replace(/\s+/g, ' ').trim() : text;
318	  return normalized.replace(/([\\`*_[\]{}<>()#+\-.!|])/g, '\\$1');
319	}
320	
321	function formatLobuViewCode(value: unknown): string {
322	  const code = String(value ?? '');
323	  const longestRun = Math.max(0, ...Array.from(code.matchAll(/`+/g), (match) => match[0].length));
324	  const fence = '`'.repeat(Math.max(3, longestRun + 1));
325	  return `${fence}\n${code}\n${fence}`;
326	}
