328	function safeLobuViewLink(href: unknown): string | null {
329	  if (typeof href !== 'string') return null;
330	  try {
331	    const url = new URL(href);
332	    if (url.protocol !== 'https:' && url.protocol !== 'http:') return null;
333	    return url.href.replace(/\(/g, '%28').replace(/\)/g, '%29');
334	  } catch {
335	    return null;
336	  }
