339	function formatLobuViewResult(result: any): string {
340	  let markdown = result.title ? `## ${escapeLobuViewMarkdown(result.title, true)}\n\n` : '';
341	  for (const block of result.blocks ?? []) {
342	    if (block.type === 'text') {
343	      markdown += `${
344	        block.label ? `**${escapeLobuViewMarkdown(block.label, true)}**\n\n` : ''
